from pydicts import lod

lod1 = [
  {"id": 1, "value": 10, "name": "A"},
  {"id": 2, "value": 20, "name": "B"} 
]

lod2 = [
  {"id": 1, "value": 5, "name": "A"},
  {"id": 3, "value": 15, "name": "C"} 
]

print("Sum:") 
lod.lod_print(lod.lod_join(lod1, lod2, calc_key="value", operation="+"))

print("\nSubtraction:")
lod.lod_print(lod.lod_join(lod1, lod2, calc_key="value", operation="-"))
